def page(filename, title, content, script):
    text = f'''<!doctype html>
<html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="description" content="Dessik: loja fictícia de tecnologia para um projeto acadêmico."><title>{title} | Dessik</title><link rel="icon" href="/images/placeholder.svg" type="image/svg+xml"><link rel="stylesheet" href="/css/style.css"><script type="module" src="/js/{script}.js"></script></head>
<body>{nav}<main id="main">{content}</main>{dialog}<footer><span><strong>dessik.</strong> Tecnologia para sua rotina.</span><span>Projeto acadêmico · Produtos e especificações fictícios</span></footer></body></html>
'''
    (root / 'public' / filename).write_text(text, encoding='utf-8')

